import os
import zipfile

def compress_logs(dir, zip_path):
    os.chmod(zip_path, 0o600)

    with zipfile.ZipFile(zip_path, 'w') as z:
        for dirpath, _, filenames in os.walk(dir):
            for f in filenames:
                if f.endswith('.log'):
                    z.write(os.path.join(dirpath, f), arcname=f)

