from urllib.parse import urlparse
import validators
import datetime
import requests

def get_metadata(url):
    if not validators.url(url):
        return None

    parsed = urlparse(url)
    domain = parsed.netloc

    if parsed.scheme not in ["http", "https"]:
        return None

    if not re.match(r'^[\w-]+\.[\w-]+\.\w+$', domain):
        return None

    resp = requests.head(url)
    last_modified = resp.headers.get("Last-Modified")
    if last_modified:
        last_modified_dt = datetime.datetime.strptime(last_modified, "%a, %d %b %Y %H:%M:%S GMT")

        return {"domain": domain, "last_modified": last_modified_dt}

    return None

